class Bag {
  final _items = <String>[];

  void add(String item) => _items.add(item);

  void addAll(List<String> items) {
    for (final item in items) {
      add(item);
    }
  }
}

class CountingBag extends Bag {
  int added = 0;

  @override
  void add(String item) {
    added++;
    super.add(item);
  }

  @override
  void addAll(List<String> items) {
    added += items.length;
    super.addAll(items);
  }
}

void main() {
  final bag = CountingBag();
  bag.addAll(['a', 'b', 'c']);
  print(bag.added);
}

